import Groq from 'groq-sdk';
import { z } from 'zod';
import { hackathonInfoSchema } from './schema.js';

// Default to llama-3.3-70b-versatile — widely available on Groq free tier,
// strong at extraction tasks, and reliably follows JSON schema constraints.
// Override with GROQ_MODEL in your .env if you want to try another model.
const MODEL = process.env.GROQ_MODEL || 'llama-3.3-70b-versatile';
const MAX_ATTEMPTS = 2;

// We use strict: false because our schema contains anyOf (generated by Zod
// for nullable fields like z.string().nullable()), which Groq's strict mode
// rejects. strict: false still enforces the schema shape at the token level —
// we just rely on Zod's .parse() below as the actual hard validation gate.
const responseFormat = {
  type: 'json_schema',
  json_schema: {
    name: 'hackathon_info',
    strict: false,
    schema: buildJsonSchema(),
  },
};

/**
 * Calls Groq to extract structured hackathon info from raw page text.
 * Validates the response with Zod before returning — schema-constrained
 * output is syntactically valid JSON, not semantically correct JSON, so
 * we always validate ourselves rather than trusting the model blindly.
 *
 * @param {string} pageText - cleaned text from fetchPageText()
 * @param {string} sourceUrl
 * @returns {Promise<import('zod').infer<typeof hackathonInfoSchema>>}
 */
export async function extractHackathonInfo(pageText, sourceUrl) {
  const apiKey = process.env.GROQ_API_KEY;
  if (!apiKey) {
    throw new Error(
      'GROQ_API_KEY is not set. Get a free key at https://console.groq.com/keys and add it to your .env file.'
    );
  }

  const groq = new Groq({ apiKey });
  const { system, user } = buildMessages(pageText, sourceUrl);

  let lastError;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const completion = await groq.chat.completions.create({
        model: MODEL,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
        response_format: responseFormat,
        temperature: 0.2, // extraction needs consistency, not creativity
      });

      const content = completion.choices[0]?.message?.content;
      if (!content) {
        throw new Error('Groq returned an empty response (no message content).');
      }

      const parsedJson = JSON.parse(content);
      // Always inject the sourceUrl — it belongs to us, not the model.
      const validated = hackathonInfoSchema.parse({ ...parsedJson, sourceUrl });
      return validated;
    } catch (err) {
      lastError = err;
      console.error(`[Scout] Extraction attempt ${attempt}/${MAX_ATTEMPTS} failed: ${err.message}`);
    }
  }

  throw new Error(
    `Scout could not extract valid structured data after ${MAX_ATTEMPTS} attempts: ${lastError.message}`
  );
}

/**
 * Splits the prompt into system + user messages.
 * System message carries the extraction rules; user message carries the data.
 * Keeping them separate makes it easier to tune or log each independently.
 *
 * @param {string} pageText
 * @param {string} sourceUrl
 * @returns {{ system: string, user: string }}
 */
function buildMessages(pageText, sourceUrl) {
  const system = `You are a precise data extraction assistant. Your only job is to extract hackathon information from raw scraped webpage text and return it as structured JSON.

Rules:
- Only extract information that is actually present in the text. Never invent dates, prize amounts, rules, or judging criteria.
- If a field is not present, use null for single values or an empty array for lists.
- Record anything important that you could NOT find in missingInfoNotes (e.g. "no judging criteria listed", "submission deadline not stated").
- Set extractionConfidence to "low" if this page looks like a marketing/landing page that links elsewhere for the real rules and details.
- The sourceUrl field will be injected after you respond — do not include it in your output.`;

  const user = `SOURCE URL: ${sourceUrl}

PAGE TEXT:
"""
${pageText}
"""

Extract all hackathon information from the text above.`;

  return { system, user };
}

/**
 * Converts hackathonInfoSchema to a plain JSON Schema for Groq's response_format.
 * Strips the $schema key (Groq ignores it) and removes sourceUrl from the
 * required list + properties — we inject that ourselves after parsing, so
 * asking the model to populate it is just noise.
 *
 * @returns {object}
 */
function buildJsonSchema() {
  const { $schema, ...jsonSchema } = z.toJSONSchema(hackathonInfoSchema);

  // sourceUrl is in the schema for Zod validation but we inject it ourselves,
  // so remove it from what we send to the model.
  const properties = { ...jsonSchema.properties };
  delete properties.sourceUrl;

  const required = (jsonSchema.required || []).filter((k) => k !== 'sourceUrl');

  return { ...jsonSchema, properties, required };
}
